// Static files the page serves, each from its single source in the repo:
// screenshots from docs/assets (regenerated by `demo:assets`), and the
// one-line installer (P5.M6.T3) at the site root.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..', '..');
const DIST = path.resolve(HERE, '..', 'dist');

fs.mkdirSync(path.join(DIST, 'screens'), { recursive: true });
for (const shot of ['ade-session.png', 'ade-approvals.png', 'ade-review.png']) {
  fs.copyFileSync(path.join(ROOT, 'docs', 'assets', shot), path.join(DIST, 'screens', shot));
}
const installer = path.join(ROOT, 'scripts', 'install', 'install.sh');
if (fs.existsSync(installer)) fs.copyFileSync(installer, path.join(DIST, 'install.sh'));
console.log('copy-static: screenshots' + (fs.existsSync(installer) ? ' + install.sh' : ''));
